const run_id = 'afishi005d-' + new Date().toISOString();
const sources = [["ru_moscow_karo","RU","Moscow","fail_closed","official_payload_not_parser_proven",null],["ru_moscow_cinemapark","RU","Moscow","fail_closed","official_payload_not_parser_proven",null],["ru_moscow_kinomax","RU","Moscow","fail_closed","official_payload_not_parser_proven",null],["uk_kyiv_multiplex","UK","Kyiv","fail_closed","worker_adapter_missing",null],["uk_kyiv_planetakino","UK","Kyiv","worker_ready",null,"planeta_kino_ua"],["uk_kyiv_oskar","UK","Kyiv","fail_closed","worker_adapter_missing",null],["cs_prague_cinemacity","CS","Prague","fail_closed","worker_adapter_missing",null],["cs_prague_cinestar","CS","Prague","worker_ready",null,"cinestar_cz"],["cs_prague_premiere","CS","Prague","worker_ready",null,"premiere_cz"],["en_london_odeon","EN","London","fail_closed","official_payload_not_parser_proven",null],["en_london_vue","EN","London","fail_closed","worker_adapter_missing",null],["en_london_cineworld","EN","London","fail_closed","official_payload_not_parser_proven",null],["pl_warsaw_cinemacity","PL","Warsaw","fail_closed","worker_adapter_missing",null],["pl_warsaw_multikino","PL","Warsaw","fail_closed","official_payload_not_parser_proven",null],["pl_warsaw_helios","PL","Warsaw","fail_closed","worker_adapter_missing",null],["sk_bratislava_cinemacity","SK","Bratislava","fail_closed","worker_adapter_missing",null],["sk_bratislava_cinemax","SK","Bratislava","fail_closed","dedicated_sk_adapter_required",null]];
return sources.map(([source_id,language,city,status,reason,adapter_key]) => ({json:{run_id,source_id,language,city,status,reason,adapter_key}}));

const source = $json;
if (source.status === 'worker_ready') {
  if (!source.adapter_key) return {json:{...source,outcome:'fail_closed',reason:'adapter_key_missing',dispatch_intent:null}};
  return {json:{...source,outcome:'worker_ready',dispatch_intent:{source_id:source.source_id,adapter_key:source.adapter_key,operation:'fetch_parse_normalize_validate'},reason:null}};
}
return {json:{...source,outcome:'fail_closed',dispatch_intent:null}};

const rows = $input.all().map(item => item.json);
const worker_ready = rows.filter(row => row.outcome === 'worker_ready').length;
const fail_closed = rows.filter(row => row.outcome === 'fail_closed').length;
return [{json:{run_id:rows[0]?.run_id ?? null,total:rows.length,worker_ready,fail_closed,complete:rows.length === 17 && worker_ready === 3 && fail_closed === 14,source_results:rows}}];

const summary = $('Aggregate Run Summary').first().json;
const raw = $input.first().json.stdout;
const bridge = JSON.parse(raw);

if (bridge.mode !== 'read_only_adapter_bridge') throw new Error('unexpected_bridge_mode');
if (bridge.production_writes !== false || bridge.schedule_activation !== false || bridge.persistence !== 'none') {
  throw new Error('read_only_boundary_violation');
}

const bridgeBySource = new Map(bridge.results.map((row) => [row.source_id, row]));
const source_results = summary.source_results.map((row) => {
  const execution = bridgeBySource.get(row.source_id);
  if (execution) return { ...row, execution };
  return {
    ...row,
    execution: {
      source_id: row.source_id,
      adapter_key: row.adapter_key,
      execution_status: 'fail_closed',
      persistence: 'none',
      fetched_at: null,
      requested_url: null,
      final_url: null,
      pages_fetched: 0,
      fetch_failures: 0,
      records_parsed: 0,
      records_valid: 0,
      parser_complete: null,
      scope_complete: null,
      screenings: [],
      errors: [row.reason || 'fail_closed'],
    },
  };
});

const statuses = source_results.map((row) => row.execution.execution_status);
const successful_sources = statuses.filter((status) => status === 'success').length;
const empty_sources = statuses.filter((status) => status === 'empty').length;
const failed_sources = statuses.filter((status) => status === 'failed').length;
const fail_closed_sources = statuses.filter((status) => status === 'fail_closed').length;

const started_at = String(summary.run_id || '').replace(/^afishi005d-/, '');
const finished_at = new Date().toISOString();
const run_date = finished_at.slice(0, 10);
const movies = new Map();
const screenings = [];
const runs = [];

for (const source of source_results) {
  const execution = source.execution;
  const rows = Array.isArray(execution.screenings) ? execution.screenings : [];
  for (const row of rows) {
    const movie_key = source.source_id + ':' + row.external_movie_id;
    if (!movies.has(movie_key)) {
      movies.set(movie_key, {
        run_date,
        source_id: source.source_id,
        movie_key,
        title: row.title,
        original_title: row.original_title ?? null,
        release_year: row.release_year ?? null,
        duration_minutes: row.duration_minutes ?? null,
        genres: Array.isArray(row.genres) ? row.genres.join('|') : '',
        poster_url: row.poster_url ?? null,
        source_url: row.source_url,
        last_seen_run_id: summary.run_id,
      });
    }
    const [local_date = '', localClock = ''] = String(row.starts_at_local || '').split('T', 2);
    screenings.push({
      run_date,
      source_id: source.source_id,
      external_screening_id: row.external_screening_id ?? null,
      movie_key,
      cinema_name: null,
      city: source.city,
      venue_timezone: row.timezone,
      starts_at: row.starts_at,
      local_date,
      local_time: localClock.slice(0, 5),
      format: row.format ?? null,
      ticket_url: row.ticket_url ?? null,
      source_url: row.source_url,
      run_id: summary.run_id,
      row_hash: row.screening_fingerprint,
    });
  }

  const movieKeys = new Set(rows.map((row) => source.source_id + ':' + row.external_movie_id));
  runs.push({
    run_id: summary.run_id,
    source_id: source.source_id,
    started_at: started_at || null,
    finished_at,
    rows_fetched: null,
    rows_parsed: execution.records_parsed ?? 0,
    movies_count: movieKeys.size,
    screenings_count: rows.length,
    is_complete: execution.execution_status !== 'failed',
    status: execution.execution_status,
    error: execution.errors?.length ? execution.errors.join('; ') : null,
  });
}

return [{json:{
  ...summary,
  snapshot_output:{
    mode:'read_only_adapter_bridge',
    live_execution:true,
    adapter_execution:true,
    worker_execution:false,
    production_writes:false,
    credential_scope:'ssh_transport_only',
    schedule_activation:false,
    persistence:'none',
    successful_sources,
    empty_sources,
    failed_sources,
    fail_closed_sources,
    pending_worker_sources:0,
    execution_complete:source_results.length === 17 &&
      successful_sources + empty_sources + failed_sources + fail_closed_sources === 17,
    source_results,
    sheet_payload:{
      mode:'google_sheets_snapshot_payload',
      production_writes:false,
      allowed_sheets:['Daily_Movies','Daily_Screenings','Daily_Runs'],
      Daily_Movies:[...movies.values()].sort((a,b)=>a.movie_key.localeCompare(b.movie_key)),
      Daily_Screenings:screenings.sort((a,b)=>a.row_hash.localeCompare(b.row_hash)),
      Daily_Runs:runs.sort((a,b)=>a.source_id.localeCompare(b.source_id)),
    },
  }
}}];

parameters.command:
set -eu
cd /opt/go-irl/cinema-worker
node --input-type=module <<'NODE'
import { planetaKinoUaAdapter } from './.cinema-worker-dist/api/_shared/cinema-adapters/planeta-kino-ua.js';
import { premiereCzAdapter } from './.cinema-worker-dist/api/_shared/cinema-adapters/premiere-cz.js';

const sources = [
  { source_id: 'uk_kyiv_planetakino', adapter_key: 'planeta_kino_ua', source_url: 'https://planetakino.ua/schedule/?cinema=cinema-1-uk', timezone: 'Europe/Kyiv' },
  { source_id: 'cs_prague_cinestar', adapter_key: 'cinestar_cz', source_url: null, reason: 'prague_venue_ambiguous' },
  { source_id: 'cs_prague_premiere', adapter_key: 'premiere_cz', source_url: 'https://www.premierecinemas.cz/', timezone: 'Europe/Prague' },
];

const adapters = { planeta_kino_ua: planetaKinoUaAdapter, premiere_cz: premiereCzAdapter };
const results = [];

for (const source of sources) {
  if (!source.source_url) {
    results.push({
      source_id: source.source_id, adapter_key: source.adapter_key, execution_status: 'fail_closed',
      persistence: 'none', fetched_at: null, requested_url: null, final_url: null,
      pages_fetched: 0, fetch_failures: 0, records_parsed: 0, records_valid: 0,
      parser_complete: null, scope_complete: null, screenings: [], errors: [source.reason],
    });
    continue;
  }

  const adapter = adapters[source.adapter_key];
  if (!adapter) throw new Error('adapter_not_allowed:' + source.adapter_key);
  const config = {
    id: 'afishi005e:' + source.source_id,
    venue_id: 'afishi005e:' + source.source_id,
    source_id: source.source_id,
    adapter_key: source.adapter_key,
    source_url: source.source_url,
    fetch_method: 'html',
    parser_version: 'afishi005e-read-only',
    timezone: source.timezone,
    enabled: false,
    fetch_interval_minutes: 1440,
    expected_horizon_days: 1,
    min_records: 1,
    config: { execution_mode: 'read_only_adapter_bridge', persistence: 'none' },
  };

  try {
    const payload = await adapter.fetchSnapshot(config);
    const parsed = adapter.parseSnapshot(config, payload);
    results.push({
      source_id: source.source_id,
      adapter_key: source.adapter_key,
      execution_status: parsed.records_valid > 0 ? 'success' : parsed.zero_result ? 'empty' : 'failed',
      persistence: 'none',
      fetched_at: payload.fetched_at,
      requested_url: source.source_url,
      final_url: payload.pages[0]?.url ?? payload.root_url,
      pages_fetched: payload.pages.length,
      fetch_failures: payload.failures.length,
      records_parsed: parsed.records_parsed,
      records_valid: parsed.records_valid,
      parser_complete: parsed.parser_complete,
      scope_complete: parsed.scope_complete,
      screenings: parsed.rows,
      errors: parsed.errors,
    });
  } catch (error) {
    results.push({
      source_id: source.source_id, adapter_key: source.adapter_key, execution_status: 'failed',
      persistence: 'none', fetched_at: null, requested_url: source.source_url, final_url: null,
      pages_fetched: 0, fetch_failures: 1, records_parsed: 0, records_valid: 0,
      parser_complete: false, scope_complete: false, screenings: [],
      errors: [error instanceof Error ? error.message : 'execution_failed'],
    });
  }
}

console.log(JSON.stringify({
  mode: 'read_only_adapter_bridge',
  live_execution: true,
  production_writes: false,
  credentials_required: true,
  credential_scope: 'ssh_transport_only',
  schedule_activation: false,
  persistence: 'none',
  results,
}));
NODE
